style.css:
body {
  width: 400px;
  height: 200px;
  border-radius: 10px;
  background: linear-gradient(120deg, #84fab0, #8fd3f4, #a8c0ff); /* Light green to light blue to light purple */
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.2);
  display: flex;
  justify-content: center;
  align-items: center;
  color: white;
  font-size: 24px;
  font-weight: bold;
  text-align: center;
  transition: transform 0.3s ease-in-out;
}
